-- 2026-09-19 / 04 / üretim-finans granular izin geçişi.
-- Uygulama DB'sinde otomatik çalışmaz. Yedek alınarak sürümlü dağıtım adımında uygulanır.
-- Tekrar çalıştırma sonradan kaldırılmış izinleri yeniden vermez.
BEGIN;

CREATE TABLE IF NOT EXISTS "KullaniciYetkileri" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "KullaniciId" integer NOT NULL REFERENCES "Kullanicilar"("Id") ON DELETE CASCADE,
  "MenuTanimiId" integer NOT NULL REFERENCES "MenuTanimlari"("Id") ON DELETE RESTRICT,
  "IzinVerildi" boolean NOT NULL,
  "CreatedDate" timestamp without time zone NOT NULL,
  "UpdatedDate" timestamp without time zone NULL,
  "CreatedBy" text NULL, "UpdatedBy" text NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_KullaniciYetkileri_KullaniciId_MenuTanimiId"
  ON "KullaniciYetkileri"("KullaniciId","MenuTanimiId");
CREATE INDEX IF NOT EXISTS "IX_KullaniciYetkileri_MenuTanimiId" ON "KullaniciYetkileri"("MenuTanimiId");

CREATE TABLE IF NOT EXISTS "YetkiDegisiklikleri" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "AktorKullaniciId" integer NOT NULL,
  "HedefTuru" varchar(30) NOT NULL, "HedefId" integer NOT NULL,
  "OncekiDeger" text NOT NULL, "YeniDeger" text NOT NULL,
  "CreatedDate" timestamp without time zone NOT NULL,
  "UpdatedDate" timestamp without time zone NULL,
  "CreatedBy" text NULL, "UpdatedBy" text NULL
);
CREATE INDEX IF NOT EXISTS "IX_YetkiDegisiklikleri_HedefTuru_HedefId_CreatedDate"
  ON "YetkiDegisiklikleri"("HedefTuru","HedefId","CreatedDate");
CREATE TABLE IF NOT EXISTS "GranularYetkiGecisleri" ("Kod" text PRIMARY KEY, "Tarih" timestamp without time zone NOT NULL);

CREATE TEMP TABLE granular_yetki_katalogu (
  id integer PRIMARY KEY, kod text NOT NULL, ad text NOT NULL,
  parent_id integer NOT NULL, gereken integer NOT NULL, kritik boolean NOT NULL
) ON COMMIT DROP;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM granular_yetki_katalogu k JOIN "MenuTanimlari" m
      ON (m."Id" = k.id OR m."Kod" = k.kod)
    WHERE m."Id" <> k.id OR m."Kod" <> k.kod
  ) THEN
    RAISE EXCEPTION 'Granular izin ID/kod çakışması var; mevcut menü eşlemesini inceleyin.';
  END IF;
END $$;

SELECT id,kod,ad,'',NULL,id,parent_id,CURRENT_TIMESTAMP AT TIME ZONE 'Europe/Istanbul'
FROM granular_yetki_katalogu
ON CONFLICT ("Kod") DO UPDATE SET "LabelKey"=EXCLUDED."LabelKey","ParentId"=EXCLUDED."ParentId";

-- İlk geçiş: eski R/W görünüm erişimini korur; W yalnız kritik olmayan yeni eylemlere taşınır.
-- Admin de bypass kullanmaz: rol 1'e açık kayıt yazılır, kişisel ret bu rolü de sınırlar.
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM "GranularYetkiGecisleri" WHERE "Kod"='20260919-granular-v1') THEN
    SELECT 1,m."Id",2,CURRENT_TIMESTAMP AT TIME ZONE 'Europe/Istanbul'
    FROM "MenuTanimlari" m WHERE m."Id" IN (46,47) AND EXISTS (SELECT 1 FROM "Roller" WHERE "Id"=1)
    ON CONFLICT ("RolId","MenuTanimiId") DO NOTHING;
    SELECT r."Id",k.id,k.gereken,CURRENT_TIMESTAMP AT TIME ZONE 'Europe/Istanbul'
    FROM "Roller" r CROSS JOIN granular_yetki_katalogu k
    WHERE r."Id"=1 OR (
      k.id<>5000 AND NOT k.kritik AND EXISTS (
        SELECT 1 FROM "RolYetkileri" eski
        WHERE eski."RolId"=r."Id" AND eski."MenuTanimiId"=k.parent_id AND eski."YetkiTipiId">=k.gereken
      )
    )
    ON CONFLICT ("RolId","MenuTanimiId") DO NOTHING;
  END IF;
END $$;
SELECT setval(pg_get_serial_sequence('"MenuTanimlari"','Id'), GREATEST((SELECT MAX("Id") FROM "MenuTanimlari"),1));
SELECT setval(pg_get_serial_sequence('"RolYetkileri"','Id'), GREATEST((SELECT MAX("Id") FROM "RolYetkileri"),1));
COMMIT;

-- Denetim çıktısı: kritik izinler ilk atamada yalnız açık Admin seed'i ve sonradan yönetici atamasıyla bulunur.
SELECT m."Kod",r."Ad",ry."YetkiTipiId"
FROM "RolYetkileri" ry JOIN "MenuTanimlari" m ON m."Id"=ry."MenuTanimiId"
JOIN "Roller" r ON r."Id"=ry."RolId"
WHERE m."Id" BETWEEN 5000 AND 5299 ORDER BY m."Kod",r."Ad";
